package com.agrolink.controller;import com.agrolink.dto.cart.*;import com.agrolink.service.CartService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/cart") public class CartController{private final CartService s;public CartController(CartService s){this.s=s;}@GetMapping public CartResponse get(Authentication a){return s.get(a.getName());}@PostMapping("/items") public CartResponse add(Authentication a,@Valid @RequestBody AddCartItemRequest r){return s.add(a.getName(),r);}@PutMapping("/items/{id}") public CartResponse update(Authentication a,@PathVariable Long id,@RequestParam double quantity){return s.update(a.getName(),id,quantity);}@DeleteMapping("/items/{id}") public void remove(Authentication a,@PathVariable Long id){s.remove(a.getName(),id);}@DeleteMapping public void clear(Authentication a){s.clear(a.getName());}}
